/// <summary>
/// CB166_SalesOrderSubstitutes
/// The <c>METSalesItemSubstituteSearch_Enabled</c> child class is responsible for the substitutes search with customer substitutions enabled = Yes.
/// </summary>
class METSalesItemSubstituteSearch_Enabled extends METSalesItemSubstituteSearch
{
    int searchDepth = 0;

}

Method.Source:
    /// <summary>
    /// search for a never first, else check the item status and search for replacement or OOS
    /// </summary>
    /// <returns>The found <c>METSalesItemSubstitute</c> record; otherwise, false.</returns>
    public METSalesItemSubstitute search()
    {
        METSalesItemSubstitute ret;

        // search for Never first
        this.parmSubstitutionCodeSet(this.createSubstitutionCodeSet(METSalesItemSubstitutionCode::Never));
        ret = super();

        if (!ret)
        {
            // search for a replacement and OOS
            this.parmSubstitutionCodeSet(this.createSubstitutionCodeSet(METSalesItemSubstitutionCode::Replacement, METSalesItemSubstitutionCode::OutOfStock));
            ret = super();
        }

        return ret;
    }

    /// <summary>
    /// Find on-hand quantity for specified item
    /// </summary>
    /// <param name = "_itemID">_itemID</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>On-hand quantity</returns>
    public Qty queryOnHandQty(ItemId _itemID, InventDim _inventDim)
    {
        InventDimParm   onHandDimParm;
        onHandDimParm.initFromInventDim(_inventDim);
        InventOnhand    onHand = InventOnhand::newItemDim(_itemId, _inventDim, onHandDimParm);
        Qty             onHandQty;
        
        onHandQty = onHand.availPhysical();

        return onHandQty;
    }

    /// <summary>
    /// Overridden method to determine if substitute exists and valid
    /// </summary>
    /// <param name = "_substituteRefRecId">Substitute record id</param>
    /// <param name = "_substituteItemId">Substitute item number</param>
    /// <param name = "_substitutionCode">Substitution code</param>
    /// <returns>True if substitute found and valid; otherwise, false</returns>
    protected boolean substituteExists(RefRecId                     _substituteRefRecId,
                                       METSubstituteItemID          _substituteItemId,
                                       METSalesItemSubstitutionCode _substitutionCode)
    {
        boolean ret = false;        

        // check if the item on the sales line is marked as Deleted.
        // If replacement and item not deleted, exit the search
        if (_substitutionCode == METSalesItemSubstitutionCode::Replacement && !MetItemSiteSettingsSetup::isItemStatus(itemId, salesItemSubstituteSearchParameters.parmInventDim().InventSiteId, METConstants::Deleted))
        {
            salesItemSubstitute = null;
            // to stop the search
            return true;
        }

        // For never do not check on hand
        if (_substitutionCode == METSalesItemSubstitutionCode::Never)
        {
            return super(_substituteRefRecId, _substituteItemId, _substitutionCode);
        }

        // If any stock is found for the substitute item (does not have to meet full ordered qty)
        if (this.queryOnHandQty(_substituteItemId, salesItemSubstituteSearchParameters.parmInventDim()))
        {
            // Substitute found and valid
            ret = super(_substituteRefRecId, _substituteItemId, _substitutionCode);
        }
        else
        {
            // Repeat from point 1 (search for an active substitute record) for the new “Substitute item” code that had no stock.
            itemId = _substituteItemId;
            substituteSiteCodeTypeEnumerator.reset();
            substitutePartyCodeTypeEnumerator.reset();
            salesItemSubstitute = null;
            continueSearchSite = false;

            // increase counter and check if it's greater that custParameters.METSalesSubstituteMaxLevels
            searchDepth++;

            // If this counter > “AR Parameters” “Max. substitute level”, then exit the substitution process for this sales line and attempt substitution for the next sales line.
            if (custParameters.METSalesSubstituteMaxLevels && searchDepth >= custParameters.METSalesSubstituteMaxLevels)
            {
                salesItemSubstitute = null;
                // to stop the search
                return true;
            }
        }

        return ret;
    }
